  'help.ticketTitle': 'Support kontaktieren',
  'help.ticketDesc': 'Erstelle ein Ticket und wir melden uns bei dir',
  'help.back': 'Zurück',
  'help.stillNeedHelp': 'Brauchen wir noch Hilfe? Erstelle ein Ticket',
  'help.createTicket': 'Support-Ticket erstellen',
  'help.ticketInfo': 'Beschreibe dein Problem und unser Team wird so schnell wie möglich antworten.',
  'help.issueType': 'Problemtyp',
  'help.yourEmail': 'Deine E-Mail',
