  'help.send': 'Ticket senden',
  'help.ticketSent': 'Ticket gesendet!',
  'help.ticketSentDesc': 'Wir haben deine Anfrage erhalten. Unser Team wird innerhalb von 24 Stunden auf deine E-Mail antworten.',
  'help.close': 'Schließen',
  'help.ticketError': 'Ticket konnte nicht gesendet werden. Bitte versuche es erneut.',
  'help.type.cant_login': 'Kann mich nicht einloggen',
  'help.type.email_issue': 'E-Mail-Problem',
  'help.type.security': 'Sicherheit',
  'help.type.other': 'Sonstiges',
  'help.faq.cantLogin.q': 'Ich kann mich nicht in mein Konto einloggen',
  'help.faq.cantLogin.a': 'Stelle sicher, dass du die richtige E-Mail und das richtige Passwort verwendest. Wenn du dein Passwort vergessen hast, klicke auf "Passwort vergessen?" auf dem Anmeldebildschirm. Wenn das Problem weiterhin besteht, erstelle ein Support-Ticket.',
  'help.faq.notReceiving.q': 'Ich erhalte keine E-Mails',
  'help.faq.notReceiving.a': 'Überprüfe zuerst deinen Spam-Ordner. Stelle sicher, dass dein Speicher nicht voll ist. Wenn das Problem weiterhin besteht, überprüfe, ob der Absender die richtige E-Mail-Adresse hat und erstelle ein Support-Ticket.',
  'help.faq.cantSend.q': 'Ich kann keine E-Mails senden',
  'help.faq.cantSend.a': 'Überprüfe deine Internetverbindung und ob die E-Mail-Adresse des Empfängers korrekt ist. Überprüfe, ob du Anhänge hast, die zu groß sind (max. 25 MB). Versuche es in ein paar Minuten erneut.',
  'help.faq.forgotPassword.q': 'Ich habe mein Passwort vergessen',
  'help.faq.forgotPassword.a': 'Klicke auf dem Anmeldebildschirm auf "Passwort vergessen?" und folge den Anweisungen, um dein Passwort über deine Wiederherstellungs-E-Mail-Adresse zurückzusetzen.',
  'help.faq.accountSecurity.q': 'Ich glaube, mein Konto wurde kompromittiert',
  'help.faq.accountSecurity.a': 'Ändere sofort dein Passwort. Überprüfe deinen Gesendet-Ordner auf Nachrichten, die du nicht gesendet hast. Aktiviere die Zwei-Faktor-Authentifizierung in Einstellungen > Sicherheit. Erstelle bei Bedarf ein dringendes Support-Ticket.',
  'help.faq.appAccess.q': 'Wie greife ich mobil auf die App zu?',
  'help.faq.appAccess.a': 'Du kannst Chatyy über jeden mobilen Browser unter chatyy.com.br aufrufen oder unsere App aus dem App-Store deines Geräts herunterladen.',

  // Privacy modal
  'privacy.title': 'Datenschutzrichtlinie',
  'privacy.subtitle': 'Wie wir deine Daten schützen und behandeln',
  'privacy.lastUpdated': 'Zuletzt aktualisiert: März 2026',
  'privacy.dataCollection.title': 'Datensammlung',
  'privacy.dataCollection.body': 'Wir sammeln nur die Informationen, die notwendig sind, um unseren E-Mail-Service bereitzustellen: deinen Namen, deine E-Mail-Adresse und den Inhalt der Nachrichten, die du sendest und empfängst. Wir verkaufen oder teilen deine persönlichen Daten nicht mit Dritten zu Marketingzwecken.',
  'privacy.dataUsage.title': 'Wie wir deine Daten verwenden',
  'privacy.dataUsage.body': 'Deine Daten werden ausschließlich verwendet, um den E-Mail-Service zu betreiben und zu verbessern, einschließlich der Zustellung von Nachrichten, der Spam-Filterung, der Bereitstellung von KI-gestützten Funktionen (mit deiner Zustimmung) und der Aufrechterhaltung der Kontosicherheit.',
  'privacy.dataSecurity.title': 'Datensicherheit',
  'privacy.dataSecurity.body': 'Wir verwenden branchenübliche Verschlüsselung (TLS/SSL) für alle Daten, die übertragen und gespeichert werden. Sitzungen sind mit verschlüsselten Tokens und CSRF-Schutz geschützt. Wir überprüfen regelmäßig unsere Sicherheitspraktiken.',
  'privacy.cookies.title': 'Cookies & Lokaler Speicher',
  'privacy.cookies.body': 'Wir verwenden essentielle Cookies und lokalen Speicher, um deine Sitzung aufrechtzuerhalten, deine Einstellungen (Thema, Sprache) zu merken und ein nahtloses Erlebnis zu bieten. Wir verwenden keine Tracking-Cookies von Drittanbietern.',
  'privacy.thirdParties.title': 'Drittanbieter-Dienste',
  'privacy.thirdParties.body': 'Wir nutzen möglicherweise Drittanbieter-Dienste für bestimmte Funktionen wie KI-Features (Anthropic Claude) und Push-Benachrichtigungen. Diese Dienste unterliegen ihren eigenen Datenschutzrichtlinien und verarbeiten nur die minimal erforderlichen Daten.',
  'privacy.rights.title': 'Deine Rechte',
  'privacy.rights.body': 'Du hast das Recht, jederzeit auf deine persönlichen Daten zuzugreifen, sie zu korrigieren, zu exportieren oder zu löschen. Du kannst deine Daten über die Einstellungen verwalten oder unser Support-Team kontaktieren.',
  'privacy.contact.title': 'Kontaktiere uns',
  'privacy.contact.body': 'Bei Fragen zum Datenschutz oder Datenanfragen kontaktiere uns unter privacy@chatyy.com.br. Wir antworten innerhalb von 30 Tagen.',

  // Terms modal
  'terms.title': 'Nutzungsbedingungen',
  'terms.subtitle': 'Richtlinien für die Nutzung von Chatyy',
  'terms.lastUpdated': 'Zuletzt aktualisiert: März 2026',
  'terms.acceptance.title': 'Akzeptanz der Bedingungen',
  'terms.acceptance.body': 'Durch den Zugriff auf oder die Nutzung von Chatyy stimmst du diesen Nutzungsbedingungen zu. Wenn du mit einem Teil dieser Bedingungen nicht einverstanden bist, darfst du den Dienst nicht nutzen.',
  'terms.services.title': 'Beschreibung der Dienste',
  'terms.services.body': 'Chatyy bietet E-Mail-Kommunikationsdienste, einschließlich Senden, Empfangen und Verwalten von E-Mails, sowie KI-gestützte Funktionen, Kalenderintegration und Videokonferenzmöglichkeiten.',
  'terms.accounts.title': 'Benutzerkonten',
  'terms.accounts.body': 'Du bist verantwortlich für die Sicherheit deiner Kontodaten. Du darfst dein Passwort nicht teilen oder unbefugten Zugriff auf dein Konto zulassen. Du musst mindestens 13 Jahre alt sein, um diesen Dienst zu nutzen.',
  'terms.conduct.title': 'Zulässige Nutzung',
  'terms.conduct.body': 'Du stimmst zu, den Dienst nicht für das Versenden von Spam, Malware, Phishing oder illegalen Inhalten zu nutzen. Du darfst nicht versuchen, auf die Konten anderer Benutzer zuzugreifen oder die Infrastruktur des Dienstes zu stören.',
  'terms.content.title': 'Inhaltsbesitz',
  'terms.content.body': 'Du behältst das Eigentum an allen Inhalten, die du über den Dienst erstellst und sendest. Wir beanspruchen kein Eigentum an deinen E-Mails oder Anhängen. Wir können Inhalte verarbeiten, soweit es notwendig ist, um den Dienst bereitzustellen.',
  'terms.limitation.title': 'Haftungsbeschränkung',
  'terms.limitation.body': 'Chatyy wird "wie besehen" bereitgestellt. Wir streben eine Verfügbarkeit von 99,9 % an, garantieren jedoch keinen ununterbrochenen Dienst. Wir sind nicht haftbar für indirekte, zufällige oder Folgeschäden, die aus deiner Nutzung des Dienstes entstehen.',
  'terms.termination.title': 'Kontokündigung',
  'terms.termination.body': 'Wir können Konten, die gegen diese Bedingungen verstoßen, sperren oder kündigen. Du kannst dein Konto jederzeit über die Einstellungen löschen. Nach der Kündigung werden deine Daten innerhalb von 30 Tagen gelöscht.',
  'terms.changes.title': 'Änderungen der Bedingungen',
  'terms.changes.body': 'Wir können diese Bedingungen von Zeit zu Zeit aktualisieren. Wir werden dich über wesentliche Änderungen per E-Mail oder In-App-Benachrichtigung informieren. Die fortgesetzte Nutzung des Dienstes nach Änderungen stellt die Akzeptanz der aktualisierten Bedingungen dar.',

