  'plans.faqWhatIsPlus': 'Was ist Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'Es ist der Premium-Plan von Chatyy, der alle deine Gespräche, Fotos und Videos schützt. Mit Chatyy One kannst du sogar, wenn du versehentlich etwas löschst, es innerhalb von 30 Tagen wiederherstellen. Du erhältst 200GB Speicher, One AI als deinen persönlichen Assistenten und kannst Dateien bis zu 100MB senden.',
